"use client";

import { FormEvent, useState } from "react";
import { useRouter } from "next/navigation";
import { api, ApiError } from "@/lib/api-client";

export default function NewServicePage(){
 const router=useRouter(); const [busy,setBusy]=useState(false); const [error,setError]=useState("");
 async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);setError("");const f=new FormData(e.currentTarget);const priceType=String(f.get("priceType")||"FIXED");const rawPrice=String(f.get("price")||"");try{await api.post("/api/services",{title:String(f.get("title")||""),description:String(f.get("description")||""),categorySlug:String(f.get("categorySlug")||"")||null,price:priceType==="QUOTE"?null:Number(rawPrice||0),priceType,location:String(f.get("location")||"")||null,serviceArea:String(f.get("serviceArea")||"")||null,bookingRequired:f.get("bookingRequired")==="on",imageUrl:null});router.push("/vendor/dashboard/services");}catch(err){setError(err instanceof ApiError?err.message:"Unable to create service");}finally{setBusy(false);}}
 return <div className="shell max-w-3xl py-8"><button type="button" onClick={()=>router.back()} className="text-sm font-semibold text-graphite-500 hover:text-ember-600">← Back</button><h1 className="mt-3 text-2xl font-bold text-graphite-900 dark:text-white">Add a service</h1><p className="mt-1 text-sm text-graphite-600 dark:text-graphite-400">Create a service listing customers can discover on TTFL Store.</p><form onSubmit={submit} className="mt-6 space-y-5 rounded-card border border-graphite-200 bg-white p-6 dark:border-graphite-700 dark:bg-graphite-900"><label className="block"><span className="text-sm font-semibold">Service name</span><input name="title" required maxLength={120} className="mt-2 field" placeholder="Phone screen replacement"/></label><label className="block"><span className="text-sm font-semibold">Description</span><textarea name="description" required minLength={10} maxLength={5000} rows={6} className="mt-2 field" placeholder="Describe what customers receive…"/></label><div className="grid gap-4 sm:grid-cols-2"><label><span className="text-sm font-semibold">Category slug</span><input name="categorySlug" className="mt-2 field" placeholder="electronics"/></label><label><span className="text-sm font-semibold">Price type</span><select name="priceType" className="mt-2 field"><option value="FIXED">Fixed price</option><option value="STARTING_FROM">Starting from</option><option value="QUOTE">Quote required</option></select></label></div><label><span className="text-sm font-semibold">Price (₦)</span><input name="price" type="number" min="0" step="0.01" className="mt-2 field" placeholder="25000"/></label><div className="grid gap-4 sm:grid-cols-2"><label><span className="text-sm font-semibold">Primary location</span><input name="location" className="mt-2 field" placeholder="Ikeja, Lagos"/></label><label><span className="text-sm font-semibold">Service area</span><input name="serviceArea" className="mt-2 field" placeholder="Lagos mainland"/></label></div><label className="flex items-center gap-3 rounded-card border border-graphite-200 p-4 dark:border-graphite-700"><input name="bookingRequired" type="checkbox" className="h-4 w-4"/><span><span className="block text-sm font-semibold">Require booking</span><span className="text-xs text-graphite-500">Customers will be expected to schedule before the service is fulfilled.</span></span></label>{error&&<p className="text-sm font-medium text-ember-600">{error}</p>}<button disabled={busy} className="w-full rounded-card bg-ember-600 px-4 py-3 text-sm font-semibold text-white hover:bg-ember-700 disabled:opacity-60">{busy?"Creating…":"Publish service"}</button></form></div>
}
